OBJECTIVES=[]
HEADINGS={'19.1':'Algorithms','19.2':'Recursion','20.1':'Programming Paradigms','20.2':'File Processing and Exception Handling','9.1':'Computational Thinking Skills','9.2':'Algorithms','10.1':'Data Types and Records','10.2':'Arrays','10.3':'Files','10.4':'Introduction to Abstract Data Types (ADT)','11.1':'Programming Basics','11.2':'Constructs','11.3':'Structured Programming','12.2':'Program Design','12.3':'Program Testing and Maintenance','13.2':'File organisation and access'}
def add(section,page,scope,en,vi,anchor,locator,links='',coverage='observed',brief='',deps=''):
    i=1+sum(o['section']==section for o in OBJECTIVES)
    oid=f'SYL-{section}-{i:02d}'
    text=pages[page]['text']; normalized=' '.join(text.split()).replace('built- in','built-in'); assert anchor in normalized,(oid,anchor)
    linked=[]
    for token in links.split():
        pat,role=token.split(':'); assert pat in patterns
        examples=[] # Filled only by the manual semantic evidence audit after all objectives exist.
        linked.append({'pattern_id':pat,'role':role,'basis':'Stage 2 capability boundary; occurrence alone does not establish every variant of this objective.','example_parts':[{'part_id':r['part_id'],'qp_basis':r['qp_basis'],'ms_basis':r['ms_basis']} for r in examples]})
    rationale={'core_practical':'Practical capability named within sections 19–20, retained even when absent from the historical corpus.','supporting_understanding':'Understanding named in 19–20 supports practical choices and traces; not promoted to a separate mandatory Paper 4 theory essay.','prerequisite':'Selected AS bridge used by practical code; not a claim that all AS objectives are independently assessed in Paper 4.','corpus_support':'Outside core 19–20; linked only to explain a corpus task or named file-processing capability.','excluded':'Explicit Paper 4 or graph-code boundary; no required practical lesson or assessment.'}[scope]
    OBJECTIVES.append({'objective_id':oid,'section':section,'scope':scope,'capability_en':en,'capability_vi':vi,'source':{'source_id':'syllabus_2026_v2','pdf_page':page,'printed_page':str(page),'heading':HEADINGS[section],'bullet_locator':locator,'anchor_text':anchor,'verification':'Natural text and rendered original page visually checked; page number matches PDF index.'},'rationale':rationale,'candidate_pattern_links':linked,'corpus_coverage':coverage,'coverage_limit':'Candidate links are capability mappings, not counts or guarantees of complete historical coverage.','gap':{'status':'not_applicable' if scope=='excluded' else ('authored_assessment_needed' if coverage in ['absent','partial','support_only'] else 'variant_completeness_check_needed'),'recommended_assessment_brief':brief or ('Author one small independent transfer check with changed data and boundary cases; do not reproduce a historical question.' if scope!='excluded' else '')},'prerequisite_objective_ids':deps.split()})
