# Scope register covers every numbered subsection listed in syllabus overview pp9–10.
AS={'1.1':'Data Representation','1.2':'Multimedia – Graphics, Sound','1.3':'Compression','2.1':'Networks including the internet','3.1':'Computers and their components','3.2':'Logic Gates and Logic Circuits','4.1':'Central Processing Unit (CPU) Architecture','4.2':'Assembly Language','4.3':'Bit manipulation','5.1':'Operating Systems','5.2':'Language Translators','6.1':'Data Security','6.2':'Data Integrity','7.1':'Ethics and Ownership','8.1':'Database Concepts','8.2':'Database Management Systems (DBMS)','8.3':'Data Definition Language (DDL) and Data Manipulation Language (DML)'}
ADV={'13.1':'User-defined data types','13.3':'Floating-point numbers, representation and manipulation','14.1':'Protocols','14.2':'Circuit switching, packet switching','15.1':'Processors, Parallel Processing and Virtual Machines','15.2':'Boolean Algebra and Logic Circuits','16.1':'Purposes of an Operating System (OS)','16.2':'Translation Software','17.1':'Encryption, Encryption Protocols and Digital certificates','18.1':'Artificial Intelligence'}
DISPOSITION=[]
for sec,title in sorted((AS|ADV|HEADINGS|{'12.1':'Program Development Life cycle'}).items(),key=lambda t:tuple(map(int,t[0].split('.')))):
    if sec in ['19.1','19.2','20.1','20.2']:status='core_and_support_with_explicit_exclusions';reason='Exhaustive atomic inventory in this file; P4 practical boundary applied.'
    elif sec=='13.2':status='conditional_support';reason='File organisation/access bridge to 20.2; in-memory hash corpus tasks kept distinct from persistent random files.'
    elif sec in HEADINGS:status='selected_prerequisite';reason='Only selected practical dependencies inventoried; not a complete AS course.'
    elif sec=='13.1':status='covered_by_prerequisite_and_oop_bridge';reason='Record and class concepts are linked via 10.1 and 20.1. No independent set/enumerated/pointer-type unit is inferred for P4.'
    elif sec=='12.1':status='outside_core';reason='No standalone development-life-cycle comparison or maintenance-theory module in this practical course.'
    else:status='outside_core';reason='Not inherited into P4 from Paper 1 or Paper 3. Any scenario vocabulary does not expand assessed scope.'
    DISPOSITION.append({'section':sec,'title':title,'disposition':status,'rationale':reason,'source':{'source_id':'syllabus_2026_v2','pdf_page':9 if int(sec.split('.')[0])<=12 else 10,'printed_page':str(9 if int(sec.split('.')[0])<=12 else 10),'heading':'Content overview'},'objective_ids':[o['objective_id'] for o in OBJECTIVES if o['section']==sec]})
CONSTRAINTS=[]
def con(i,page,statement,anchor,kind='assessment'):
 assert anchor in ' '.join(pages[page]['text'].split()),(i,anchor)
 CONSTRAINTS.append({'constraint_id':f'P4-ADM-{i:02d}','type':kind,'statement':statement,'source':{'source_id':'syllabus_2026_v2','pdf_page':page,'printed_page':str(page),'anchor_text':anchor}})
con(1,11,'Paper 4 is 150 minutes, 75 marks and 25% of A Level.','2 hours 30 minutes 75 marks')
con(2,40,'Practical application of sections 19–20 excludes low-level and declarative programming.','except for low-level and declarative programming.')
con(3,13,'AO3 is 100% of Paper 4; design, program and evaluate solutions with reasoned judgements.','Design, program and evaluate computer systems to solve problems, making reasoned judgements about these.')
con(4,11,'Candidates submit complete code and testing evidence.','Candidates will submit complete program code and evidence of testing.')
con(5,11,'Permitted languages are Java, Visual Basic (.NET) or Python, console mode. This course chooses Python by user instruction.','Python (console mode) programming languages.')
con(6,40,'Centre computers have no internet or email access.','these must not have internet access or access to email.')
con(7,11,'Calculators are not permitted.','Calculators must not be used in any paper.')
con(8,40,'Provided source files contain no binary files; random-file processing remains in 20.2.','The source files given will not contain binary files.')
con(9,40,'Save the provided evidence document with centre number, candidate name and candidate number.','should be saved with the centre number, candidate’s name and candidate’s number.')
con(10,40,'Copy requested program listings or result screenshots into the evidence document.','copy program listings or take screenshots of results to paste into the evidence document.')
con(11,40,'Save work regularly; centres are recommended to enable autosave.','Candidates must save their work at regular intervals')
con(12,40,'Work absent from the evidence document receives no marks.','If there is no evidence of work in the evidence document, the work will not receive any marks.')
con(13,39,'Facilities must support direct-access backing-store files and hardcopy.','direct-access file capability on backing store and hardcopy facilities.','teacher_guidance')
con(14,39,'Develop a systematic practical problem-solving approach and use adequate book coverage.','Teachers will need to consult several books to cover the whole syllabus adequately.','teacher_guidance')
